#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
  const grace = Date.now() + ERROR_GRACE;
  while (Date.now() < deadline) {
    if (!already && await done()) return true;
    const visible = await error.isVisible().catch(() => false);
    if (stale === undefined) stale = visible ? await shown(error) : null;
    if (visible) {
      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
    } else {
      seenGone = true;
    }
    // the state held before the action: an error still showing at the grace outranks it
    if (already && Date.now() >= grace && await done()) return true;
    await page.waitForTimeout(50);
  }
  if (await done()) return true;
  if (await error.isVisible().catch(() => false)) return false;
  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
}

